export function progressComparison(rows){const ids=[...new Set(rows.map(r=>r.signal))];return ids.map(signal=>{const all=rows.filter(r=>r.signal===signal),valid=all.filter(r=>r.resolved),first=valid.filter(r=>!r.review).slice(0,5),review=valid.filter(r=>r.review).slice(-5),mean=a=>a.length?Math.round(a.reduce((n,r)=>n+r.points,0)/a.length):null;return {signal,label:all[0].label,first:mean(first),review:mean(review),firstCount:first.length,reviewCount:review.length,delta:first.length&&review.length?mean(review)-mean(first):null,level:adaptiveLevel(rows,signal)};});}
export function adaptiveLevel(rows,signal){const recent=rows.filter(r=>r.signal===signal&&r.resolved).slice(-5),mean=recent.length?recent.reduce((n,r)=>n+r.points,0)/recent.length:0,clean=recent.filter(r=>!r.errors&&!r.hints&&!r.revealed).length;if(recent.length>=3&&mean>=85&&clean>=3)return 'advanced';if(recent.length>=3&&mean>=65)return 'practice';return 'support';}
export const levelLabels={support:'Apoyo · 2 opciones y orientación',practice:'Práctica · 4 opciones',advanced:'Reto · señal y sentido del cambio'};
export function adaptPrediction(event,rows){const e=structuredClone(event),level=adaptiveLevel(rows,e.answer.id);e.level=level;if(level==='support'){const correct=e.options.find(o=>o.id===e.answer.id),wrong=e.options.find(o=>o.id!==e.answer.id);e.options=e.index%2?[correct,wrong]:[wrong,correct];}if(level==='advanced'){const make=(o,from,to)=>({...o,id:o.id+':'+from+'-'+to,label:o.label+' · '+from+' → '+to});const answer=e.options.find(o=>o.id===e.answer.id),wrong=e.options.filter(o=>o.id!==e.answer.id).slice(0,2);e.options=[make(answer,0,1),make(answer,1,0),...wrong.flatMap(o=>[make(o,0,1),make(o,1,0)])];const shift=e.index%e.options.length;e.options.push(...e.options.splice(0,shift));e.correctId=e.answer.id+':'+e.answer.from+'-'+e.answer.to;}return e;}
export function renderProgressChart(host,rows){host.replaceChildren();const title=document.createElement('h3');title.textContent='Primeros ejercicios frente a repasos recientes';host.append(title);const note=document.createElement('p');note.textContent='Escala 0–100. Primeras 5 preguntas resueltas sin repaso frente a las últimas 5 de repaso por señal. Se muestran las disponibles; pendientes excluidas. El grupo de repaso incluye los exámenes. Sin datos no equivale a cero. Las dificultades pueden variar: la diferencia describe tus resultados, no una prueba equivalente.';host.append(note);const data=progressComparison(rows);if(!data.length){const p=document.createElement('p');p.textContent='Completa ejercicios y repasos para construir tu gráfica.';host.append(p);}for(const s of data){const row=document.createElement('section');row.className='signal-chart-row';const h=document.createElement('h4');h.textContent=s.label;row.append(h);for(const [key,label,count]of [['first','Primeros',s.firstCount],['review','Repasos',s.reviewCount]]){const line=document.createElement('div');line.className='score-bar-row';const text=document.createElement('span');text.textContent=label+' (n='+count+')';const meter=document.createElement('meter');meter.min=0;meter.max=100;meter.value=s[key]??0;meter.className=key;meter.setAttribute('aria-label',s.label+' · '+label+(s[key]===null?' · sin datos':' · '+s[key]+' de 100'));meter.hidden=s[key]===null;const output=document.createElement('span');output.textContent=s[key]===null?'Sin datos':s[key]+'/100';line.append(text,meter,output);row.append(line);}const caption=document.createElement('p');caption.textContent=(s.delta===null?'Falta uno de los grupos para comparar.':'Cambio: '+(s.delta>0?'+':'')+s.delta+' puntos.')+' Próximo nivel: '+levelLabels[s.level];row.append(caption);host.append(row);}}
